import{z as A,x as d,o as s,c as B,q as n,j as o,D as r,d as t,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"纵深防御","description":"","frontmatter":{"title":"纵深防御","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/defense-in-depth.md","filePath":"cs/defense-in-depth.md","lastUpdated":1791413859000}'),p={name:"cs/defense-in-depth.md"};function h(c,a,S,m,f,C){const l=d("Mermaid");return s(),B("div",null,[a[2]||(a[2]=n('<h1 id="纵深防御" tabindex="-1">纵深防御 <a class="header-anchor" href="#纵深防御" aria-label="Permalink to &quot;纵深防御&quot;">​</a></h1><div class="epigraph"><p>纵深防御假设单层会失败：编码、CSP、沙箱、分段、检测同时在。它反对银弹，也反对无限叠加造成无法运维的疲劳。</p><footer>—— 据 NSA 对纵深的传统陈述；Saltzer and Schroeder；对照本课程各层控制</footer></div><p>上一课<a href="/cs/zero-trust-architecture">零信任</a>是一架构原则。缺口是<strong>多层同时存在</strong>如何排：每层对应哪类失败。本课收口策略图。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只 WAF、只 MFA、只加密——单层把全部预算押在一个机制上，该机制失效防护即归零。缺口是映射：预防、检测、响应各覆盖哪类失败，每层把攻击者推进到哪一步必须新增能力——新漏洞、新凭据、物理接触，而不是同一工具重放。可用安全警告层数太多则被关：告警疲劳让操作员关掉控制，层数本身有运维成本。</p><p><span class="marginnote">直觉类比：纵深防御像中世纪城堡——护城河之外还有外墙、内墙、塔楼哨兵。护城河干涸（WAF 被绕过），攻城者还得面对下一层，每过一层都要新增能力（新攻城梯、新内应），而不是把同一招重放到底。</span></p><h3 id="独立失败" tabindex="-1">独立失败 <a class="header-anchor" href="#独立失败" aria-label="Permalink to &quot;独立失败&quot;">​</a></h3><p>两层若同一根因（同一密钥），不是纵深。判据是失败模式相关还是独立：输出编码挡注入、CSP 挡执行、HttpOnly 挡窃取，三者对 <a href="/cs/xss">XSS</a> 是三种机制；WAF 与应用共用一套正则引擎则共享缺陷，一击穿即双穿。</p><p><span class="marginnote">数字实例：若三层独立、各层失效概率 10%，攻破全部三层的概率是 0.1% = 千分之一；但若两层共用同一个正则引擎，第一层被打穿时第二层同步失效，防线实际只剩单层——概率退回 10%。值得数的是「独立失败模式数」，不是层数。</span></p><p><span class="marginnote">Saltzer。TCB 最小化下一课防止纵深变成巨大不可审 TCB。NSA 的 IATF 把纵深写成人员、技术、操作三域；Saltzer-Schroeder 八原则里最近的近亲是 separation of privilege。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按 CIA 与杀伤链映射已讲控制：机密性靠加密与访问控制，完整性靠签名与 WORM，可用性靠冗余与限流；杀伤链各段配检测点——侦察、落点、驻留、横移、外送。设计次序是先钉每层挡什么失败，再选机制，不是先买产品再找位置；检测层要演练，规则无人响应等于没有；预防层与检测层分属不同失效假设，前者赌挡住，后者赌漏过。下一课 TCB 最小化。</p>',13)),(s(),o(E,null,{default:r(()=>[i(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E9%A2%84%E9%98%B2%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20RESP%5B%22%E5%93%8D%E5%BA%94%22%5D%0A%20%20PRE%20--%3E%20IND%5B%22%E5%B1%82%E5%BA%94%E7%8B%AC%E7%AB%8B%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[t("零信任是一层策略；纵深是多失败模式。零信任收紧「信任如何授予」，纵深回答「单层失效谁兜底」，二者正交：零信任网络内部仍要检测与响应。纵深与 TCB 有张力：每加一层多一块必须正确配置与审计的信任面，层叠到不可审即违背最小 TCB。经济失败模式：N 层的维护成本与告警量线性涨，各层误报相乘后放大，纵深退化成运维与预算问题（回 "),e("a",{href:"/cs/security-economics"},"安全经济学"),t("）。TCB 下一课限制信任计算基体积。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为层数越多越安全，于是七八种告警全开。每层都有维护成本与误报率，告警疲劳会把操作员逼成「一律点忽略」——防线被自己的噪音从内部关掉。层要精而独立，不是多。")],-1)),(s(),o(E,null,{default:r(()=>[i(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E6%94%BB%E5%87%BB%E6%AD%A5%E9%AA%A4%201%EF%BC%9Apayload%20%E6%B3%A8%E5%85%A5%22%5D%20--%3E%20D1%5B%22%E5%B1%82%201%EF%BC%9A%E8%BE%93%E5%87%BA%E7%BC%96%E7%A0%81%E8%AE%A9%E5%AE%83%E4%B8%8D%E6%98%AF%E4%BB%A3%E7%A0%81%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E6%AD%A5%E9%AA%A4%202%EF%BC%9A%E6%B5%8F%E8%A7%88%E5%99%A8%E6%89%A7%E8%A1%8C%22%5D%0A%20%20S2%20--%3E%20D2%5B%22%E5%B1%82%202%EF%BC%9ACSP%20%E6%8B%A6%E4%B8%8B%E5%86%85%E8%81%94%E8%84%9A%E6%9C%AC%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E6%AD%A5%E9%AA%A4%203%EF%BC%9A%E8%84%9A%E6%9C%AC%E5%81%B7%20cookie%22%5D%0A%20%20S3%20--%3E%20D3%5B%22%E5%B1%82%203%EF%BC%9AHttpOnly%20%E8%AE%A9%20JS%20%E8%AF%BB%E4%B8%8D%E5%88%B0%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有产品堆进去：层数不是指标，独立失败模式数才是。TCB 最小化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>零信任不取消其他层。</li><li>层必须独立失败模式。</li><li>太多层会被人关掉。</li><li>下一课 TCB 最小化。</li><li>出处：Saltzer and Schroeder；NSA 纵深陈述。</li></ul>',4))])}const T=A(p,[["render",h]]);export{D as __pageData,T as default};
